<script setup lang="ts">
import{reactive,ref,watch}from'vue';import{ElForm,ElFormItem,ElInput,ElSelect,ElOption,ElButton,ElAlert,ElMessage}from'element-plus';import{requestClient}from'#/api/request';const props=defineProps<{projectId:string}>();const loading=ref(false),saving=ref(false),error=ref('');const form=reactive({medium:'',level:'GUIDED',hazards:'',guidance:'',source:''});async function load(){loading.value=true;error.value='';try{const data=await requestClient.get<typeof form>(`/growth/safety/${props.projectId}`);Object.assign(form,data.level==='UNKNOWN'?{medium:'',level:'GUIDED',hazards:'',guidance:'',source:''}:data)}catch{error.value='安全标注加载失败，请重试'}finally{loading.value=false}}async function save(){if(!Object.values(form).every(v=>v.trim())){ElMessage.warning('请填写完整的材料、安全措施与依据');return}saving.value=true;try{await requestClient.put(`/growth/safety/${props.projectId}`,form);ElMessage.success('安全说明已保存')}catch{}finally{saving.value=false}}watch(()=>props.projectId,load,{immediate:true});
</script><template><div v-loading="loading" style="max-width:760px"><ElAlert title="依据实际材料、工具及厂商说明标注。不要把未经核验的安全信息交给 AI 补写。" type="info" :closable="false"/><ElAlert v-if="error" :title="error" type="error" :closable="false"/><ElForm label-position="top" style="margin-top:20px"><ElFormItem label="材料类别"><ElSelect v-model="form.medium"><ElOption v-for="m in ['染','塑','织绣','纸','香','雕']" :key="m" :label="m" :value="m"/></ElSelect></ElFormItem><ElFormItem label="操作级别"><ElSelect v-model="form.level"><ElOption label="常规注意" value="LOW"/><ElOption label="需在指导下操作" value="GUIDED"/><ElOption label="高风险工具 / 材料" value="HIGH"/></ElSelect></ElFormItem><ElFormItem label="风险与不适用情形"><ElInput v-model="form.hazards" type="textarea" maxlength="300" placeholder="实际涉及的过敏源、锐器、高温等；无已知特殊风险也须说明"/></ElFormItem><ElFormItem label="防护、通风与操作要求"><ElInput v-model="form.guidance" type="textarea" :rows="4" maxlength="1000"/></ElFormItem><ElFormItem label="核验依据"><ElInput v-model="form.source" maxlength="300" placeholder="材料说明书、工具操作规范及核验人"/></ElFormItem><ElButton type="primary" :loading="saving" :disabled="loading||!!error" @click="save">保存安全说明</ElButton><ElButton @click="load">重新加载</ElButton></ElForm></div></template>
